// Generated by AI (UnitTest MCP)
use super::{opt_i64, rendered_result};
use mindleak_core::MindLeak;
use serde_json::{json, Value};

pub(super) fn definitions() -> Vec<Value> {
    vec![json!({
        "name": "telemetry_snapshot",
        "description": "Return the observability record (ADR-0010): per-tool lifetime calls/errors/latency, current health, recent invocations, and bounded per-session memory-read-before-first-write habits. Lifetime errors are cumulative history; current health follows each tool's latest call.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "limit": { "type": "integer", "default": 20, "minimum": 1, "maximum": 500, "description": "How many recent events to include." }
            }
        }
    })]
}

pub(super) fn dispatch(
    engine: &MindLeak,
    name: &str,
    args: &Value,
) -> Option<Result<Value, String>> {
    match name {
        "telemetry_snapshot" => Some((|| {
            let limit = opt_i64(args, "limit", 20).clamp(1, 500) as usize;
            let snapshot = engine
                .telemetry_snapshot(limit)
                .map_err(|e| e.to_string())?;
            let health = if snapshot.currently_failing_tools == 0 {
                "all tools healthy".to_string()
            } else {
                format!(
                    "{} tool(s) currently failing",
                    snapshot.currently_failing_tools
                )
            };
            let mut markdown = format!(
                "**MindLeak telemetry** - {} events, {} lifetime errors, {}\n\nLifetime errors are cumulative history; **Health** reflects each tool's most recent call.\n\n| Tool | Calls | Lifetime errors | Health | Avg ms | Max ms |\n|---|--:|--:|:--|--:|--:|\n",
                snapshot.total_events, snapshot.total_errors, health
            );
            for metric in &snapshot.by_name {
                let tool_health = if metric.currently_failing {
                    "failing"
                } else {
                    "ok"
                };
                markdown.push_str(&format!(
                    "| {} | {} | {} | {} | {:.1} | {} |\n",
                    metric.name,
                    metric.calls,
                    metric.errors,
                    tool_health,
                    metric.avg_ms,
                    metric.max_ms
                ));
            }
            if !snapshot.memory_habits.is_empty() {
                markdown.push_str(
                    "\n**Memory habit** - successful reads and attributed writes since each session's latest registration.\n\n| Session | Reads | Writes | Read before first write |\n|---|--:|--:|:--|\n",
                );
                for habit in &snapshot.memory_habits {
                    let verdict = match habit.read_before_first_write {
                        Some(true) => "yes",
                        Some(false) => "no",
                        None => "unknown",
                    };
                    markdown.push_str(&format!(
                        "| {} | {} | {} | {} |\n",
                        habit.agent_id, habit.memory_reads, habit.attributed_writes, verdict
                    ));
                }
            }
            Ok(rendered_result(markdown, &json!(snapshot)))
        })()),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn snapshot_renders_memory_habit_and_keeps_it_structured() {
        let engine = MindLeak::open_in_memory().unwrap();
        engine.record_tool_call("open_session", true, 0, None, Some("session:a"));
        engine.record_tool_call("recall", true, 1, None, Some("session:a"));
        engine.record_tool_call("ingest_file", true, 1, None, Some("session:a"));

        let result = dispatch(&engine, "telemetry_snapshot", &json!({}))
            .unwrap()
            .unwrap();
        let markdown = result["content"][0]["text"].as_str().unwrap();

        assert!(markdown.contains("**Memory habit**"));
        assert!(markdown.contains("| session:a | 1 | 1 | yes |"));
        assert_eq!(
            result["structuredContent"]["memory_habits"][0]["read_before_first_write"],
            true
        );
    }
}
